        const optional = authored?.optional === true;
        const canPark = () => ctx.turnMode() === "interactive" && !optional;
        const giveUp = () => {
            if (optional) {
                // The original error lets `resolveAdvertisedTools` skip the connection.
                this.logger(`[session] skipping optional MCP connection ${connection}: authorization required`);
                throw error;
            }
            if (authored !== undefined && !canPark()) {
                throw new McpReconnectError(authored.name, mcpAuthReconnectMessage(authored), error);
            }
            throw error;
        };
        // Only `oauth: true` can recover without a person, from a saved token.
        const canRefresh = authored !== undefined && isHostOauthConnectionTransport(authored.transport);
        if (!canPark() && !canRefresh) {
            return giveUp();
        }
        const minted = await this.mintAuthUrl(connection, ctx.sessionId);
        if (minted === undefined) {
            return giveUp();
        }
        if ("authorized" in minted) {
            await this.persistHostedMcpOauth(connection);
            await this.mcpHost.dropClient(connection);
            return await this.withMcpAuth(connection, run);
        }
        if (minted.state !== "") {
            const bind = this.oauthHub.bind(minted.state, ctx.sessionId, ctx.callId);
            if (bind === "already_done") {
                await this.persistHostedMcpOauth(connection);
                await this.mcpHost.dropClient(connection);
                return await this.withMcpAuth(connection, run);
            }
        }
        if (!canPark()) {
            if (minted.state !== "") {
                await this.oauthHub.abortCall(ctx.sessionId, ctx.callId);
            }
            return giveUp();
        }
