        await this.updateRecord(sessionId, (current) => ({
            ...current,
            continuationKey: token,
        }));
        if (token !== null) {
            this.releasedContinuations.delete(token);
        }
        else if (previous?.continuationKey != null) {
            this.releasedContinuations.delete(previous.continuationKey);
            this.releasedContinuations.add(previous.continuationKey);
            // Only a hosted guest takes these; the cap bounds a serve that never does.
            if (this.releasedContinuations.size > RELEASED_CONTINUATIONS_CAP) {
                const oldest = this.releasedContinuations.values().next().value;
                if (oldest !== undefined) {
                    this.releasedContinuations.delete(oldest);
                }
            }
        }
        // Keep armed reminders addressed at the conversation across channel
        // continuation rotation.
